// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily } = loadMontserrat();



export type PodiumBlocksProps = Record<string, any>;

const PodiumBlocks: React.FC<PodiumBlocksProps> = ({
  backgroundColor = "#07071a",
  transparentBackground = false,
  durationInSeconds = 5,
  blocks = [
    { text: "1", color: "#0066ff" },
    { text: "2", color: "#ff7700" },
    { text: "3", color: "#8800ff" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = Math.round(durationInSeconds * fps);

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive canvas-relative dimensions
  const blockW = width * 0.25;
  const gap = width * 0.025;
  const blockH = blockW * 1.5;
  const midBlockH = blockW * 1.7;
  const radius = blockW * 0.15;
  const fontSize = blockW * 0.8;
  const extrusionHeight = width * 0.02;

  // Ensure we only process up to 3 blocks for this specific composition
  const displayBlocks = blocks.slice(0, 3);

  // --- Animation Timings ---
  // Entrances
  const midEntranceFrame = 10;
  const leftEntranceFrame = 15;
  const rightEntranceFrame = 20;

  const midSpring = spring({ frame: frame - midEntranceFrame, fps, config: { damping: 14, mass: 1.2 } });
  const leftSpring = spring({ frame: frame - leftEntranceFrame, fps, config: { damping: 14, mass: 1.2 } });
  const rightSpring = spring({ frame: frame - rightEntranceFrame, fps, config: { damping: 14, mass: 1.2 } });

  // Exits (last 30 frames)
  const exitStartFrame = durationInFrames - 30;
  const exitSpring = spring({ frame: frame - exitStartFrame, fps, config: { damping: 12 } });
  const exitY = interpolate(exitSpring, [0, 1], [0, height]);

  // Particles (Burst on middle block impact around frame 25)
  const particleBurstProgress = spring({ frame: frame - 23, fps, config: { damping: 20 } });
  
  const particles = useMemo(() => {
    return Array.from({ length: 50 }).map((_, i) => {
      const angle = random(`angle-${i}`) * Math.PI * 2;
      // Focus particles slightly more upwards
      const adjustedAngle = angle > 0 && angle < Math.PI ? angle : angle + (Math.PI / 4) * (random(`adjust-${i}`) > 0.5 ? 1 : -1);
      const speed = random(`speed-${i}`) * (width * 0.4) + (width * 0.1);
      const size = random(`size-${i}`) * (width * 0.006) + 2;
      const colorChoices = ["#ffffff", "#00d4ff", "#ff8a00", "#d100ff"];
      const color = colorChoices[Math.floor(random(`color-${i}`) * colorChoices.length)];
      const delay = random(`delay-${i}`) * 0.3; // Stagger effect via parameter manipulation
      return { angle: adjustedAngle, speed, size, color, delay };
    });
  }, [width]);

  // Camera Shake
  const getShake = (f: number, impactFrame: number) => {
    const timeSinceImpact = f - impactFrame;
    if (timeSinceImpact < 0 || timeSinceImpact > 15) return 0;
    const amplitude = interpolate(timeSinceImpact, [0, 15], [width * 0.015, 0], { extrapolateRight: "clamp" });
    return Math.sin(timeSinceImpact * 2) * amplitude;
  };

  const shakeX = getShake(frame, 30) * 0.5 + getShake(frame, 35) * -0.5; // Left/Right impacts shake horizontally
  const shakeY = getShake(frame, 25) * 1; // Heavy middle impact shakes vertically

  // --- Rendering Helpers ---
  const getBlockPosition = (index: number) => {
    if (index === 1) return { targetX: 0, startX: 0, targetY: 0, startY: -height, currentSpring: midSpring };
    if (index === 0) return { targetX: -(blockW + gap), startX: -width, targetY: 0, startY: 0, currentSpring: leftSpring };
    return { targetX: blockW + gap, startX: width, targetY: 0, startY: 0, currentSpring: rightSpring };
  };

  const renderBlock = (block: { text: string; color: string }, index: number, isReflection = false) => {
    const pos = getBlockPosition(index);
    const isMiddle = index === 1;
    const h = isMiddle ? midBlockH : blockH;
    
    const currentX = interpolate(pos.currentSpring, [0, 1], [pos.startX, pos.targetX]);
    const currentY = interpolate(pos.currentSpring, [0, 1], [pos.startY, pos.targetY]);

    // Shines trigger shortly after landing
    const shineStartFrame = isMiddle ? 35 : index === 0 ? 40 : 45;
    const shineProgress = interpolate(frame, [shineStartFrame, shineStartFrame + 20], [-150, 150], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

    // Inner block styles (3D extrusion and shading)
    const blockStyle: React.CSSProperties = {
      position: "absolute",
      width: blockW,
      height: h,
      backgroundColor: block.color,
      borderRadius: radius,
      transform: `translate(-50%, -100%)`, // anchor to bottom center
      overflow: "hidden",
      boxShadow: isReflection ? "none" : `
        inset 0px ${width * 0.01}px ${width * 0.015}px rgba(255,255,255,0.4),
        inset 0px -${width * 0.01}px ${width * 0.02}px rgba(0,0,0,0.5),
        0px ${extrusionHeight}px 0px rgba(0,0,0,0.6),
        0px ${width * 0.04}px ${width * 0.05}px rgba(0,0,0,0.8)
      `,
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
    };

    return (
      <div key={`block-${index}-${isReflection}`} style={{
        position: "absolute",
        left: currentX,
        top: currentY,
        width: 0,
        height: 0,
        transition: "none",
        zIndex: isMiddle ? 10 : 5,
      }}>
        <div style={blockStyle}>
          <div style={{
            fontSize,
            fontWeight: 900,
            color: "white",
            textShadow: `0px ${width * 0.01}px ${width * 0.02}px rgba(0,0,0,0.4)`,
            transform: `translateY(-${width * 0.01}px)`, // slight optical adjustment for heavy bottom shadow
          }}>
            {block.text}
          </div>

          {/* Shine Sweep */}
          <div style={{
            position: "absolute",
            top: 0, bottom: 0, left: 0, right: 0,
            background: `linear-gradient(105deg, transparent 40%, rgba(255,255,255,0.6) 48%, rgba(255,255,255,0.9) 50%, rgba(255,255,255,0.6) 52%, transparent 60%)`,
            transform: `translateX(${shineProgress}%)`,
            pointerEvents: "none",
          }} />
        </div>
      </div>
    );
  };

  // Flares between blocks
  const renderFlare = (xPos: number, impactFrame: number) => {
    const flareOpacity = interpolate(
      frame,
      [impactFrame, impactFrame + 5, impactFrame + 30],
      [0, 1, 0.2],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
    
    return (
      <div style={{
        position: "absolute",
        left: xPos,
        top: -midBlockH * 0.5,
        width: width * 0.6,
        height: width * 0.6,
        transform: "translate(-50%, -50%)",
        background: "radial-gradient(circle, rgba(255,255,255,0.8) 0%, rgba(255,255,255,0.2) 20%, transparent 60%)",
        opacity: flareOpacity,
        mixBlendMode: "screen",
        pointerEvents: "none",
        zIndex: 8,
      }} />
    );
  };

  // Group of all blocks for easy duplication (reflection)
  const BlockGroup = ({ isReflection = false }) => (
    <>
      {displayBlocks.map((b, i) => renderBlock(b, i, isReflection))}
    </>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, overflow: "hidden" }}>
      {/* Background Lighting/Spotlight */}
      <div style={{
        position: "absolute", inset: 0,
        background: `radial-gradient(circle at 50% 30%, rgba(255,255,255,0.15) 0%, transparent 70%)`
      }} />

      {/* Main Container - Centered, handles global shake and exit */}
      <div style={{
        position: "absolute",
        left: width / 2,
        top: height / 2 + midBlockH * 0.3, // Anchor slightly below center for balance
        width: 0, height: 0,
        transform: `translate(${shakeX}px, ${shakeY + exitY}px)`,
        transition: "none",
      }}>
        
        {/* Particles Layer (Behind Blocks) */}
        <svg width={width * 2} height={height * 2} style={{
          position: "absolute",
          top: -height, left: -width,
          overflow: "visible",
          pointerEvents: "none"
        }}>
          <g transform={`translate(${width}, ${height - midBlockH * 0.5})`}>
            {particles.map((p, i) => {
              // Modify progress with particle's deterministic delay
              const pProgress = Math.max(0, particleBurstProgress - p.delay);
              if (pProgress <= 0) return null;
              
              const currentDist = interpolate(pProgress, [0, 1], [0, p.speed]);
              const pLength = interpolate(pProgress, [0, 0.2, 1], [0, p.speed * 0.4, 0]);
              const pOpacity = interpolate(pProgress, [0, 0.8, 1], [1, 1, 0]);

              const x1 = Math.cos(p.angle) * currentDist;
              const y1 = Math.sin(p.angle) * currentDist;
              const x2 = Math.cos(p.angle) * (currentDist + pLength);
              const y2 = Math.sin(p.angle) * (currentDist + pLength);

              return (
                <line
                  key={`p-${i}`}
                  x1={x1} y1={y1} x2={x2} y2={y2}
                  stroke={p.color}
                  strokeWidth={p.size}
                  strokeLinecap="round"
                  opacity={pOpacity}
                  style={{ transition: "none" }}
                />
              );
            })}
          </g>
        </svg>

        {/* The Actual Blocks */}
        <BlockGroup />

        {/* Flares at Intersections */}
        {renderFlare(-(blockW * 0.5 + gap * 0.5), 30)}
        {renderFlare((blockW * 0.5 + gap * 0.5), 35)}

        {/* Floor Reflection System */}
        <div style={{
          position: "absolute",
          left: 0,
          top: extrusionHeight, // Start just below the block extrusion
          width: 0, height: 0,
          transform: `scaleY(-1)`,
          filter: `blur(${width * 0.015}px)`,
          opacity: 0.5,
          zIndex: 1, // behind flares and normal blocks
        }}>
          <BlockGroup isReflection={true} />
        </div>
      </div>

      {/* Reflection Fade Overlay (Replaces CSS mask-image) */}
      <div style={{
        position: "absolute",
        left: 0, right: 0, bottom: 0,
        height: height * 0.4, // Covers the bottom portion where reflection lives
        background: `linear-gradient(to bottom, ${transparentBackground ? 'transparent' : 'rgba(7,7,26,0.3)'} 0%, ${bgColor} 80%)`,
        zIndex: 2,
        pointerEvents: "none"
      }} />
      
    </AbsoluteFill>
  );
};

export default PodiumBlocks;